declare_lint ! { #[doc = " The `if_let_rescope` lint detects cases where a temporary value with"] #[doc = " significant drop is generated on the right hand side of `if let`"] #[doc = " and suggests a rewrite into `match` when possible."] #[doc = ""] #[doc = " ### Example"] #[doc = ""] #[doc = " ```rust,edition2021"] #[doc = " #![warn(if_let_rescope)]"] #[doc = " #![allow(unused_variables)]"] #[doc = ""] #[doc = " struct Droppy;"] #[doc = " impl Drop for Droppy {"] #[doc = "     fn drop(&mut self) {"] #[doc = "         // Custom destructor, including this `drop` implementation, is considered"] #[doc = "         // significant."] #[doc = "         // Rust does not check whether this destructor emits side-effects that can"] #[doc = "         // lead to observable change in program semantics, when the drop order changes."] #[doc = "         // Rust biases to be on the safe side, so that you can apply discretion whether"] #[doc = "         // this change indeed breaches any contract or specification that your code needs"] #[doc = "         // to honour."] #[doc = "         println!(\"dropped\");"] #[doc = "     }"] #[doc = " }"] #[doc = " impl Droppy {"] #[doc = "     fn get(&self) -> Option<u8> {"] #[doc = "         None"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " fn main() {"] #[doc = "     if let Some(value) = Droppy.get() {"] #[doc = "         // do something"] #[doc = "    }
else {"] #[doc = "         // do something else"] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " {{produces}}"] #[doc = ""] #[doc = " ### Explanation"] #[doc = ""] #[doc = " With Edition 2024, temporaries generated while evaluating `if let`s"] #[doc = " will be dropped before the `else` block."] #[doc = " This lint captures a possible change in runtime behaviour due to"] #[doc = " a change in sequence of calls to significant `Drop::drop` destructors."] #[doc = ""] #[doc = " A significant [`Drop::drop`](https://doc.rust-lang.org/std/ops/trait.Drop.html)"] #[doc = " destructor here refers to an explicit, arbitrary implementation of the `Drop` trait on the type"] #[doc = " with exceptions including `Vec`, `Box`, `Rc`, `BTreeMap` and `HashMap`"] #[doc = " that are marked by the compiler otherwise so long that the generic types have"] #[doc = " no significant destructor recursively."] #[doc = " In other words, a type has a significant drop destructor when it has a `Drop` implementation"] #[doc = " or its destructor invokes a significant destructor on a type."] #[doc = " Since we cannot completely reason about the change by just inspecting the existence of"] #[doc = " a significant destructor, this lint remains only a suggestion and is set to `allow` by default."] #[doc = ""] #[doc = " Whenever possible, a rewrite into an equivalent `match` expression that"] #[doc = " observe the same order of calls to such destructors is proposed by this lint."] #[doc = " Authors may take their own discretion whether the rewrite suggestion shall be"] #[doc = " accepted, or rejected to continue the use of the `if let` expression."] pub IF_LET_RESCOPE , Allow , "`if let` assigns a shorter lifetime to temporary values being pattern-matched against in Edition 2024 and \
    rewriting in `match` is an option to preserve the semantics up to Edition 2021" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: EditionSemanticsChange (Edition :: Edition2024) , reference : "<https://doc.rust-lang.org/edition-guide/rust-2024/temporary-if-let-scope.html>" ,}
; }